#!/bin/bash
# Example job script submitted via the end-of-turn YAML block.
#
# This runs inside the compute container with:
#   - Your workspace mounted at /home/user
#   - GPU(s) available
#   - No internet access
#
# Make sure all data, code, and dependencies are already in the
# workspace or baked into the container before submitting.

set -e

cd /home/user

# Artifact-contract validation run: regenerate the all-target EEGNet
# synthetic-random ranking artifact with candidate embeddings. The raw-EEG
# artifact was regenerated by job f55aef50-ae1, so this job restores the
# secondary representation experiment and then evaluates both artifacts
# together.
export PROTOCOL="${PROTOCOL:-synthetic_random}"
export N_TARGETS="${N_TARGETS:-17}"
export N_OBSERVATIONS="${N_OBSERVATIONS:-500}"
export N_SPLITS="${N_SPLITS:-5}"
export SEED="${SEED:-0}"
export EEG="${EEG:-eeg_net}"
export OUTPUT="${OUTPUT:-outputs/cursor_ranking_eegnet_n500.json}"
export CONTINUE_EXISTING=1

bash scripts/method.sh
bash scripts/evaluate.sh outputs/cursor_ranking.json "${OUTPUT}"
